(() => {
'use strict';
const app=document.getElementById('app'),modalRoot=document.getElementById('modal-root');
const themes={a:{name:'清雅诗笺',tag:'一字为令 · 以诗相会',verse:'且将新火试新茶，诗酒趁年华。',seal:'以诗会友'},b:{name:'墨韵擂台',tag:'诗词擂台 · 一字一会',verse:'腹有诗书气自华。',seal:'诗词雅集'},c:{name:'晴山诗会',tag:'山水有诗 · 你我有约',verse:'明月松间照，清泉石上流。',seal:'山水之间'}};
let levels={easy:{label:'简单',rounds:5,seconds:null,hints:2},normal:{label:'正常',rounds:10,seconds:null,hints:0},hard:{label:'困难',rounds:15,seconds:null,hints:0},endless:{label:'无限',rounds:null,seconds:null,hints:null}};
const store={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}},remove(k){try{localStorage.removeItem(k)}catch{}}};
const stages={all:'不限',primary:'小学',junior:'初中',senior:'高中'};
function resultStage(items){
    if(!items?.length)return '';
    const stage=s.stage!=='all'&&items.includes(s.stage)?s.stage:['primary','junior','senior'].find(v=>items.includes(v));
    return stage?`<span class="result-tags"><span>${stages[stage]}</span></span>`:'';
}
const s={page:'home',word:'月',difficulty:'easy',theme:store.get('feihualing.theme')||'a',game:null,mode:'word',query:'月',queryDraft:'月',searched:false,searchLoading:false,answer:'',results:[],total:0,more:false,feedback:'',busy:false,network:false,offset:0,stage:'all',stageDraft:'all',corpusVersion:'',records:[],recordsMore:false,recordsCursor:null,recordsLoading:false,recordGame:null,recordLoading:false,supportQrOpen:true,user:null,authMode:'register',authBusy:false,authError:'',feedbackDraft:{kind:'suggestion',body:'',contact:''},feedbackRequest:null,feedbackSent:'',feedbackBusy:false};
if(!themes[s.theme])s.theme='a';
let followBottom=true,wantBottom=false,renderFrame=0,unseen=false,receivedSeq=0,historyLoading=false;
let toastTimer,lastFocus,modalKind='',pending=null,polling=false,searchSeq=0,resultShown='',fullPoemText='',composing=false,recordScroll=0;
let identityEpoch=0,supportVisibleIdentity=null;const activeRequests=new Set();
const reader={key:'',pieces:[],index:0,token:0};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const icons=()=>window.lucide.createIcons({attrs:{'aria-hidden':'true'}});
const highlight=(t,w=s.game?.word||s.word)=>w?esc(t).split(esc(w)).join(`<mark>${esc(w)}</mark>`):esc(t);
const active=()=>s.game&&['playing','processing'].includes(s.game.status);
const requestId=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'_'+Math.random().toString(36).slice(2);
const pageVisitId=requestId();let visitRecorded=false;
function readerButton(key,label='朗读诗句'){
    return `<button class="icon-btn read-btn ${reader.key===key?'speaking':''}" data-read="${esc(key)}" type="button" aria-label="${reader.key===key?'停止朗读':label}" aria-pressed="${reader.key===key}" title="${reader.key===key?'停止朗读':label}">${icon(reader.key===key?'square':'volume-2')}</button>`;
}
function refreshReaderButtons(){document.querySelectorAll('[data-read]').forEach(b=>{const on=b.dataset.read===reader.key;b.classList.toggle('speaking',on);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',on?'停止朗读':'朗读诗句');b.title=on?'停止朗读':'朗读诗句';b.innerHTML=icon(on?'square':'volume-2')});icons()}
function stopReading(){reader.token++;reader.key='';reader.pieces=[];reader.index=0;window.speechSynthesis?.cancel();refreshReaderButtons()}
function readingPieces(text){const pieces=[];for(const part of text.match(/[^。！？；，、\n]+[。！？；，、\n]?/g)||[]){if(part.trim())for(let i=0;i<part.length;i+=80)pieces.push(part.slice(i,i+80))}return pieces}
function readText(key,text){
    if(reader.key===key){stopReading();return}
    stopReading();
    if(!window.speechSynthesis?.speak||typeof window.SpeechSynthesisUtterance!=='function'){toast('当前浏览器不支持朗读，请在系统浏览器打开');return}
    sendEvent('read_aloud');reader.key=key;reader.pieces=readingPieces(text);reader.index=0;const token=reader.token;refreshReaderButtons();
    const speakNext=()=>{if(token!==reader.token)return;if(reader.index>=reader.pieces.length){stopReading();return}try{const utterance=new SpeechSynthesisUtterance(reader.pieces[reader.index++]);utterance.lang='zh-CN';utterance.rate=.9;const voices=speechSynthesis.getVoices();utterance.voice=voices.find(v=>/^zh[-_]CN/i.test(v.lang))||voices.find(v=>/^zh/i.test(v.lang))||null;utterance.onend=speakNext;utterance.onerror=()=>{if(token===reader.token){stopReading();toast('朗读未能播放，请在系统浏览器打开')}};speechSynthesis.speak(utterance)}catch{stopReading();toast('朗读未能播放，请在系统浏览器打开')}};
    speakNext();
}
function toast(message,kind='info'){
    const notice=document.getElementById('toast');
    notice.textContent=message;
    notice.dataset.kind=kind;
    notice.setAttribute('role',kind==='error'?'alert':'status');
    notice.setAttribute('aria-live',kind==='error'?'assertive':'polite');
    notice.classList.add('visible');
    clearTimeout(toastTimer);
    toastTimer=setTimeout(()=>notice.classList.remove('visible'),2600);
}
async function api(path,options={}){
    const epoch=identityEpoch,controller=new AbortController();activeRequests.add(controller);
    const timeout=setTimeout(()=>controller.abort(),22000);
    try{const response=await fetch(path,{credentials:'same-origin',...options,signal:controller.signal});const data=await response.json();if(epoch!==identityEpoch){const error=new Error('账号已切换');error.stale=true;throw error}if(!response.ok){const error=new Error(typeof data.detail==='string'?data.detail:'操作未完成，请检查输入后重试');error.status=response.status;throw error}s.network=false;return data}
    catch(e){if(epoch!==identityEpoch){e.stale=true;throw e}if(e.name==='AbortError'||e instanceof TypeError){s.network=true;throw new Error('连接中断，请重试；已保存的记录不受影响')}throw e}
    finally{clearTimeout(timeout);activeRequests.delete(controller)}
}
const json=(body)=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
function applyProfile(profile){s.user=profile;s.stage=stages[profile.education_stage]?profile.education_stage:'all';s.stageDraft=s.stage;s.authMode=profile.kind==='account'?'credentials':'register'}
function clearPrivateState(){identityEpoch++;for(const controller of activeRequests)controller.abort();activeRequests.clear();stopReading();closeModal();searchSeq++;pending=null;polling=false;receivedSeq=0;recordScroll=0;historyLoading=false;resultShown='';fullPoemText='';store.remove('feihualing.game');Object.assign(s,{user:null,game:null,recordGame:null,records:[],recordsMore:false,recordsCursor:null,recordsLoading:false,recordLoading:false,results:[],total:0,more:false,searched:false,searchLoading:false,query:'月',queryDraft:'月',answer:'',feedback:'',busy:false,authError:'',authBusy:false,feedbackBusy:false,feedbackSent:'',feedbackRequest:null,feedbackDraft:{kind:'suggestion',body:'',contact:''},supportQrOpen:true});s.page='me';window.history.replaceState(null,'','#me');render()}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function guestSession(){
    const create=()=>api('/api/auth/guest',json({}));
    if(navigator.locks?.request)return navigator.locks.request('feihualing.guest-bootstrap',create);
    const key='feihualing.bootstrap-lock',token=requestId();
    const readLock=()=>{try{return JSON.parse(store.get(key)||'null')}catch{return null}};
    for(let attempt=0;attempt<160;attempt++){
        const lock=readLock();
        if(!lock||lock.until<Date.now()){
            const value=JSON.stringify({token,until:Date.now()+30000});store.set(key,value);
            // Storage may be unavailable in a private/embedded browser.
            if(store.get(key)===null)return create();
            await delay(60+Math.random()*40);
            if(readLock()?.token===token){try{return await create()}finally{if(readLock()?.token===token)store.remove(key)}}
        }
        await delay(200);
    }
    throw new Error('另一个页面正在准备账号，请稍后刷新');
}
function sendEvent(action){if(!s.user)return;fetch('/api/events',{credentials:'same-origin',...json({action,request_id:requestId()})}).catch(()=>{})}
function accountPanel(){
    const u=s.user;if(!u)return '<section class="account-panel"><p>正在准备你的游客身份…</p><button class="secondary" data-action="retry-boot">重新连接</button></section>';
    const guest=u.kind==='guest',mode=guest?s.authMode:'credentials';
    return `<section class="account-panel" aria-label="我的账号"><div class="account-identity"><strong>${esc(u.display_name||u.username||'游客')}</strong><span>${guest?'游客':'已保存账号'}</span></div>${guest?'<p>直接免费使用，也可以保存账号，在其他设备继续对诗。</p>':`<p>账号名：${esc(u.username)}</p>`}${u.must_change_password?'<p class="account-warning" role="alert">你正在使用临时密码，请先设置新密码。</p>':''}${guest?`<div class="account-tabs"><button data-auth-mode="register" aria-pressed="${mode==='register'}">保存当前账号</button><button data-auth-mode="login" aria-pressed="${mode==='login'}">登录已有账号</button></div>`:`<details class="account-settings" ${u.must_change_password?'open':''}><summary>修改账号名或密码</summary>`}<form id="account-form" class="community-form" data-mode="${mode}" data-identity="${esc(u.id)}">${mode==='credentials'?'<label>当前密码<input name="current_password" type="password" autocomplete="current-password" required maxlength="128"></label>':''}<label>${mode==='credentials'?'新账号名（不修改可留空）':'账号名'}<input name="username" autocomplete="username" minlength="2" maxlength="32" ${mode==='credentials'?'':'required'} autocapitalize="none" spellcheck="false"></label><label>${mode==='credentials'?'新密码（不修改可留空）':'密码'}<input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" ${mode==='credentials'&&!u.must_change_password?'':'required'} ${mode==='login'?'':'minlength="8"'} maxlength="128"></label>${mode==='login'?'<p class="form-note">登录会切换身份，当前游客记录不会自动并入已有账号。暂不支持自助找回密码。</p>':'<p class="form-note">密码至少 8 个字符。暂不支持自助找回，请妥善保存账号名和密码。</p>'}<div id="account-error" class="feedback" role="status">${esc(s.authError)}</div><button class="primary" ${s.authBusy?'disabled':''}>${s.authBusy?'正在处理…':mode==='login'?'登录':mode==='register'?'保存账号':'保存修改'}</button></form>${guest?'':'</details>'}${!guest?`<button class="secondary" data-action="logout" ${s.authBusy?'disabled':''}>退出账号</button>`:''}${u.role==='admin'?'<a class="admin-entry" href="/admin">打开管理后台</a>':''}</section>`;
}
function feedbackPage(){const d=s.feedbackDraft;return `<main class="shell personal-shell">${header()}<section class="personal-content"><div class="personal-heading"><button class="icon-btn" data-action="me" aria-label="返回我的">${icon('chevron-left')}</button><h1>意见反馈</h1></div><p class="community-intro">遇到问题、发现诗文有误，或有想加入的功能，都可以告诉我。</p>${s.feedbackSent?`<div class="feedback-success" role="status"><strong>反馈已收到，谢谢你。</strong><p>反馈编号：${esc(s.feedbackSent)}</p><button class="secondary" data-action="feedback-another">再写一条</button></div>`:`<form id="feedback-form" class="community-form" data-identity="${esc(s.user?.id)}"><label>反馈类型<select name="kind">${Object.entries({bug:'使用问题',suggestion:'功能建议',content:'诗文纠错',other:'其他'}).map(([k,v])=>`<option value="${k}" ${d.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><label>反馈内容<textarea name="body" rows="6" required minlength="5" maxlength="3000" placeholder="请描述遇到的情况；诗文纠错可写下作品名和原句。">${esc(d.body)}</textarea></label><label>联系方式（选填）<input name="contact" value="${esc(d.contact)}" maxlength="200" placeholder="邮箱或其他便于回复的方式" autocomplete="email"></label><p class="form-note">请勿填写密码等敏感信息。提交后会保存反馈，并通知作者查看；无需重复提交。</p><div class="feedback" role="status">${esc(s.feedback)}</div><button class="primary" ${s.feedbackBusy?'disabled':''}>${s.feedbackBusy?'正在提交…':'提交反馈'}</button></form>`}<p class="community-privacy">网站记录使用时间和功能操作，活动明细保留 90 天，不在活动记录中保存搜索词或诗句内容。反馈内容及选填联系方式会提供给作者，用于处理问题。</p>${active()?'<button class="secondary" data-action="support-resume">继续当前对局</button>':''}</section>${nav()}</main>`}
async function submitAccount(form){
    if(s.authBusy)return;const mode=form.dataset.mode,values=Object.fromEntries(new FormData(form)),epoch=identityEpoch;
    s.authBusy=true;s.authError='';form.querySelector('button[type="submit"],button.primary').disabled=true;
    try{
        let profile;
        if(mode==='credentials'){const payload={current_password:values.current_password};if(values.username.trim())payload.username=values.username.trim();if(values.password)payload.password=values.password;if(!payload.username&&!payload.password)throw new Error('请填写新账号名或新密码');profile=await api('/api/auth/credentials',json(payload))}
        else if(mode==='register')profile=await api('/api/auth/register',json({username:values.username.trim(),password:values.password}));
        else{const payload={username:values.username.trim(),password:values.password,confirm_switch:false};try{profile=await api('/api/auth/login',json(payload))}catch(e){if(e.status!==409)throw e;if(!window.confirm('切换账号不会合并当前游客记录。建议先保存当前游客账号，以便日后找回。仍要登录已有账号吗？'))return;payload.confirm_switch=true;profile=await api('/api/auth/login',json(payload))}}
        if(epoch!==identityEpoch)return;clearPrivateState();applyProfile(profile);store.set('feihualing.auth-change',requestId());s.feedback=mode==='register'?'账号已保存':mode==='login'?'登录成功':'账号信息已更新';render();toast(s.feedback,'success');
        if(profile.must_change_password){document.querySelector('.account-settings')?.setAttribute('open','');document.querySelector('[name="current_password"]')?.focus()}
    }catch(e){if(epoch===identityEpoch){s.authError=e.message;const notice=document.getElementById('account-error');if(notice)notice.textContent=e.message;toast(e.message,'error')}}
    finally{if(epoch===identityEpoch){s.authBusy=false;if(form.isConnected)form.querySelector('button.primary').disabled=false;else render()}}
}
async function signOut(){if(s.authBusy||!window.confirm('退出后会使用新的游客身份。已保存的账号可重新登录。'))return;s.authBusy=true;try{await api('/api/auth/logout',json({}));clearPrivateState();store.set('feihualing.auth-change',requestId());applyProfile(await guestSession());render()}catch(e){if(!e.stale){s.feedback=e.message;s.authBusy=false;render()}}}
async function submitFeedback(form){if(s.feedbackBusy)return;const epoch=identityEpoch;Object.assign(s.feedbackDraft,Object.fromEntries(new FormData(form)));s.feedbackRequest ||= requestId();s.feedbackBusy=true;s.feedback='';render();try{const result=await api('/api/feedback',json({...s.feedbackDraft,request_id:s.feedbackRequest}));if(epoch!==identityEpoch)return;s.feedbackSent=result.id;s.feedbackDraft={kind:'suggestion',body:'',contact:''};s.feedbackRequest=null}catch(e){if(epoch===identityEpoch)s.feedback=e.message}finally{if(epoch===identityEpoch){s.feedbackBusy=false;render()}}}
async function boot(){
    const epoch=identityEpoch;
    try{
        const profile=await guestSession();if(epoch!==identityEpoch)return;applyProfile(profile);
        if(profile.must_change_password){s.page='me';window.history.replaceState(null,'','#me');render();return}
        if(!visitRecorded)fetch('/api/visits',{credentials:'same-origin',...json({request_id:pageVisitId})}).then(r=>{if(r.ok)visitRecorded=true}).catch(()=>{});
        const config=await api('/api/config');levels=config.levels||levels;const id=store.get('feihualing.game');
        if(id){try{const r=await api('/api/games/'+id);s.game=r.game;receivedSeq=r.game.message_count;wantBottom=true;followBottom=true}catch(e){if(e.stale)return;if(e.status===404){store.remove('feihualing.game');s.game=null;s.records=[];s.recordGame=null}}}
        if(epoch!==identityEpoch)return;
        const route=location.hash.slice(1),explicit=['me','support','feedback','records','search'].includes(route)||route.startsWith('records/');
        if(active()&&!explicit)window.history.replaceState(null,'','#battle');s.page=active()&&!explicit?'battle':['search','me','support','feedback','records'].includes(route)?route:route.startsWith('records/')?'record':'home';render();
        if(s.page==='search')lookup(false,false);if(s.page==='records')loadRecords();if(s.page==='record'){const id=route.slice(8);if(/^[a-f0-9]{32}$/.test(id))openRecord(id)}if(s.game?.candidates?.length&&s.page==='battle')showCandidates(s.game.candidates);
        if(profile.must_change_password){s.page='me';location.hash='me';render();document.querySelector('.account-settings')?.setAttribute('open','')}
    }catch(e){if(epoch===identityEpoch){s.feedback=e.message;s.page='me';render()}}
}
document.addEventListener('submit',e=>{if(e.target.id==='account-form'){e.preventDefault();submitAccount(e.target)}if(e.target.id==='feedback-form'){e.preventDefault();submitFeedback(e.target)}});
document.addEventListener('input',e=>{if(e.target.form?.id==='feedback-form'&&e.target.form.isConnected&&e.target.form.dataset.identity===s.user?.id){s.feedbackDraft[e.target.name]=e.target.value;s.feedbackRequest=null}});
document.addEventListener('change',e=>{if(e.target.form?.id==='feedback-form'&&e.target.form.isConnected&&e.target.form.dataset.identity===s.user?.id){s.feedbackDraft[e.target.name]=e.target.value;s.feedbackRequest=null}});
document.addEventListener('click',e=>{
    if(e.target.closest('.author-support-links a[download]'))sendEvent('support_save');
    const b=e.target.closest('button');if(!b)return;
    if(b.dataset.authMode){s.authMode=b.dataset.authMode;s.authError='';render()}
    if(b.dataset.action==='logout')signOut();
    if(b.dataset.action==='retry-boot')boot();
    if(b.dataset.action==='feedback-another'){s.feedbackSent='';s.feedback='';render()}
});
window.addEventListener('storage',async e=>{if(e.key!=='feihualing.auth-change')return;clearPrivateState();try{let profile;try{profile=await api('/api/me')}catch(error){if(error.status!==401)throw error;profile=await guestSession()}applyProfile(profile);render();toast('账号状态已在其他页面更新')}catch(error){if(!error.stale){s.feedback=error.message;render()}}});

function applyAppearance(){document.body.dataset.theme=s.theme;document.title=`飞花令 · ${themes[s.theme].name}`;document.querySelector('meta[name="theme-color"]').content={a:'#18574c',b:'#a93335',c:'#237765'}[s.theme]}
function setGame(g){
    if(!g)return;const old=s.game,same=old?.id===g.id;if(same&&(g.revision||0)<(old.revision||0))return;
    const incoming=g.messages||[],newMessages=same&&incoming.some(m=>m.seq>receivedSeq);
    if(same){const bySeq=new Map(old.messages.map(m=>[m.seq,m]));incoming.forEach(m=>bySeq.set(m.seq,m));g.messages=[...bySeq.values()].sort((a,b)=>a.seq-b.seq);g.messages=followBottom?g.messages.slice(-200):g.messages.slice(0,200)}
    receivedSeq=Math.max(same?receivedSeq:0,...incoming.map(m=>m.seq));
    s.game=g;store.set('feihualing.game',g.id);
    const changed=!same||newMessages||old.status!==g.status||old.hints!==g.hints||old.message_count!==g.message_count;
    if(newMessages){if(followBottom)wantBottom=true;else unseen=true}
    if(s.page==='battle'&&changed)render();
    if(!active()&&s.page==='battle'&&resultShown!==g.id+g.status){resultShown=g.id+g.status;showResult()}
    if(g.candidates?.length&&s.page==='battle'&&!modalKind)showCandidates(g.candidates);
}
function header(battle=false){return `<header class="topbar">${battle?`<div class="subheader"><button class="icon-btn" data-action="exit" aria-label="退出对局">${icon('chevron-left')}</button><span>飞花令</span><span class="level-label">${s.game.level.label}</span></div>`:`<a class="brand" href="#home"><span class="seal">令</span>飞花令</a>`}<div class="top-actions"><button class="icon-btn" data-action="theme" aria-label="界面主题">${icon('palette')}</button><button class="icon-btn" data-action="rules" aria-label="玩法说明">${icon('circle-help')}</button></div></header>`}
function nav(){return `<nav class="bottom-nav" aria-label="主导航"><a href="#home" class="${s.page==='home'?'active':''}">${icon('swords')}人机对战</a><a href="#search" class="${s.page==='search'?'active':''}">${icon('book-open')}查诗</a><a href="#me" class="${['me','records','record','support','feedback'].includes(s.page)?'active':''}">${icon('user-round')}我的</a></nav>`}
function home(){const t=themes[s.theme],l=levels[s.difficulty];return `<main class="shell home-shell">${header()}<section class="hero"><div class="eyebrow">${t.tag}</div><h1>飞花令</h1><p class="verse">${t.verse}</p><span class="hero-seal">${t.seal}</span></section><figure class="art-strip"><img src="/assets/landscape-${s.theme}.jpg" alt="王翚古典山水画"><figcaption class="art-caption">一山一水一诗心</figcaption></figure><section class="setup"><div class="section-label"><label for="word">今日，飞什么字？</label><small>自选令字</small></div><div class="word-line"><input id="word" class="word-input" value="${esc(s.word)}" maxlength="2" aria-label="飞花令字" autocomplete="off"><div class="popular-words">${['月','花','春','山','风','雪','雨','江'].map(w=>`<button class="word-btn ${w===s.word?'selected':''}" data-word="${w}">${w}</button>`).join('')}</div></div><div class="difficulty"><div class="section-label"><span>选择难度</span><small>以诗作答，轮流接令</small></div><div class="segments">${Object.entries(levels).map(([k,v])=>`<button class="segment ${k===s.difficulty?'selected':''}" data-level="${k}" aria-pressed="${k===s.difficulty}">${v.label}<small>${v.rounds===null?'不限回合':v.rounds+' 轮获胜'}</small></button>`).join('')}</div><div class="rule-note"><span>${icon('coffee')}不限时</span><span>${icon('lightbulb')}${l.hints===null?'无限提示':l.hints?'2 次提示':'无提示'}</span><span>${icon('refresh-cw')}答错可重试</span></div></div><div class="feedback">${esc(s.feedback)}</div><button class="primary" data-action="start" ${s.busy?'disabled':''}>${s.busy?'正在入席…':'开始对战'} ${icon('arrow-right')}</button><button class="lookup-shortcut" data-action="search"><span>${icon('book-open')}查诗</span><small>寻一句诗，赴一场会</small>${icon('chevron-right')}</button></section>${nav()}</main>`}
function history(game=s.game,prefix='battle'){return game.messages.length?game.messages.map(m=>`${m.who==='player'?`<div class="round-label">第 ${m.round} 回合</div>`:''}<article class="poem-message ${m.who}" data-seq="${m.seq}"><div class="speaker">${icon(m.who==='player'?'user-round':'bot')}${m.who==='player'?'你':'诗友'}</div><div class="poem-text">${highlight(m.text,game.word)}</div><div class="poem-source"><span>${esc(m.dynasty)} · ${esc(m.author)}《${esc(m.title)}》</span><span class="correct-icon">${icon('check')}</span>${prefix==='record'&&m.poem_id?`<button class="icon-btn" data-poem="${esc(m.poem_id)}" aria-label="查看全文" title="查看全文">${icon('book-open')}</button>`:''}${readerButton(prefix+'-'+m.seq)}</div></article>`).join(''):prefix==='battle'?'<div class="empty">一字起，诗意生。<small>写下第一句诗，开启这场诗会。</small></div>':'<div class="empty">这一局还没有接令诗句。</div>'}
function battle(){const g=s.game;return `<main class="shell battle-shell">${header(true)}${s.network?'<div class="network-note">连接中断，正在尝试恢复…</div>':''}<section class="battle-top"><div class="battle-meta"><span>${g.level.rounds===null?`已完成 <b>${g.round}</b> 回合`:`第 <b>${Math.min(g.round+1,g.level.rounds)}</b> / ${g.level.rounds} 轮`}</span><span>${g.level.rounds===null?'无限接令':g.level.rounds+' 轮获胜'}</span><span>不限时</span></div>${g.level.rounds===null?'':`<div class="progress-track">${Array.from({length:g.level.rounds},(_,i)=>`<i class="${i<g.round?'done':''}"></i>`).join('')}</div>`}<div class="arena"><div class="player-id"><span class="avatar computer">${icon('bot')}</span><span>诗友<small>电脑对手</small></span></div><div class="token"><small>本局令字</small><strong>${esc(g.word)}</strong></div><div class="player-id"><span>你<small>以诗会友</small></span><span class="avatar">你</span></div></div></section><section class="history" id="history" aria-label="对战诗句记录">${g.messages[0]?.seq>1?`<button class="more-btn" data-action="older" ${historyLoading?'disabled':''}>${historyLoading?'加载中…':'查看更早记录'}</button>`:''}${history()}<div class="your-turn">${active()?'轮到你了':'本局已结束'}</div></section><button class="latest-btn" data-action="latest" ${unseen||!followBottom?'':'hidden'}>回到最新 ↓</button><section class="composer"><div class="composer-top"><span class="turn-caption">请接一句含「${esc(g.word)}」的诗</span><button class="hint-btn" data-action="hint" ${!active()||g.hints===0||s.busy?'disabled':''}>${icon('lightbulb')}提示 · ${g.hints===null?'不限次':g.hints}</button></div><div class="feedback" role="status">${esc(s.feedback||((s.busy||g.status==='processing')?'正在核对诗句…':''))}${pending&&!s.busy?'<button class="retry-btn" data-action="retry">重试提交</button>':''}</div><form class="answer-form" id="answer-form"><input id="answer" aria-label="输入诗句" value="${esc(s.answer)}" placeholder="输入你想到的诗句…" autocomplete="off" ${!active()||g.status==='processing'||s.busy?'disabled':''}><button class="send-btn" aria-label="提交诗句" ${!active()||g.status==='processing'||s.busy?'disabled':''}>${icon('arrow-up')}</button></form>${!active()?'<button class="primary" data-action="result">查看结算</button>':''}</section></main>`}
function search(){const mode=s.mode,wordMode=mode==='word';return `<main class="shell search-shell">${header()}<section class="search-controls"><div class="search-heading"><h1>寻诗</h1><span>优先：${stages[s.stage]}</span></div><div class="search-modes" role="group" aria-label="搜索方式">${Object.entries({word:'令字',author:'作者',text:'诗句'}).map(([k,label])=>`<button data-mode="${k}" aria-pressed="${mode===k}" class="${mode===k?'selected':''}">${label}</button>`).join('')}</div><form class="search-form" id="search-form">${icon('search')}<input id="search-word" aria-label="${wordMode?'查诗汉字':mode==='author'?'作者姓名':'诗句关键词'}" placeholder="${wordMode?'输入一个汉字':mode==='author'?'输入作者，如李白':'输入诗句，如床前明月光'}" value="${esc(s.queryDraft)}" maxlength="${wordMode?2:160}"><button ${s.searchLoading?'disabled':''}>${s.searchLoading?'查找中':'查诗'}</button></form>${wordMode?`<div class="search-popular"><span>常用令字</span>${['月','花','春','山','风','雪'].map(w=>`<button data-query="${w}">${w}</button>`).join('')}</div>`:''}<div class="results-bar"><span>${s.searched?(wordMode?`含「<b>${esc(s.query)}</b>」的诗词 <b>${s.total}</b> 条`:`本库找到 <b>${s.total}</b> 首作品`):'输入关键词，找一首诗'}</span><span>${wordMode?'上下句优先':'按作品计数'}</span></div></section><section class="search-results" id="search-results" aria-label="查诗结果">${s.results.map((r,i)=>`<article class="result-item"><button class="result-open" data-poem="${r.poem_id}">${!wordMode?`<strong class="result-title">${esc(r.title)}</strong>`:''}<span class="result-line">${highlight(r.text,wordMode?s.query:r.match_text)}</span><span class="result-source">${esc(r.dynasty)} · ${mode==='author'?highlight(r.author,s.query):esc(r.author)}《${esc(r.title)}》</span>${resultStage(r.education_stages)}</button>${readerButton('search-'+i)}<button class="icon-btn" data-copy="${esc(r.text)}" aria-label="复制诗句">${icon('copy')}</button></article>`).join('')}${!s.results.length?`<div class="empty">${s.searched?'暂无相关作品':'诗词与知己，都可寻。'}</div>`:''}<div class="feedback" role="status">${esc(s.feedback)}</div>${s.more?`<button class="more-btn" data-action="more" ${s.searchLoading?'disabled':''}>${s.searchLoading?'加载中…':'查看更多'} ${icon('chevron-down')}</button>`:''}${!wordMode&&s.searched?'<p class="search-note">同篇多处命中只计一首；本库收录的不同版本分别计数。</p>':''}</section><footer class="search-footer">${wordMode&&s.searched?`<div class="search-start"><button class="primary" data-action="search-start">以「${esc(s.query)}」为令 ${icon('swords')}</button></div>`:''}${nav()}</footer></main>`}
function me(){if(s.user?.must_change_password)return `<main class="shell personal-shell">${header()}<section class="personal-content"><h1>设置新密码</h1>${accountPanel()}</section></main>`;return `<main class="shell personal-shell">${header()}<section class="personal-content"><h1>我的</h1>${accountPanel()}<div class="personal-section"><div class="section-label"><span>诗词学段</span><small>查诗时优先显示</small></div><div class="stage-options" role="radiogroup" aria-label="诗词学段">${Object.entries(stages).map(([key,label])=>`<label class="stage-option"><input type="radio" name="stage" value="${key}" ${s.stageDraft===key?'checked':''}><span>${label}</span></label>`).join('')}</div><button class="primary" data-action="save-stage" ${s.busy||s.stageDraft===s.stage?'disabled':''}>保存设置</button></div><button class="personal-link" data-action="records">${icon('history')}<span>对战记录</span>${icon('chevron-right')}</button><button class="personal-link" data-action="feedback">${icon('message-square')}<span>意见反馈</span>${icon('chevron-right')}</button><button class="personal-link author-support-link" data-action="support">${icon('heart')}<span>支持作者</span>${icon('chevron-right')}</button><p class="identity-note">${s.user?.kind==='account'?'使用账号名和密码，可在其他设备查看自己的记录。':'已为你保留游客身份。设置账号名和密码后，可在其他设备继续使用；清除浏览器 Cookie 后无法找回未保存的游客身份。'}</p><p class="community-privacy">网站记录使用时间和功能操作，活动明细保留 90 天，不在活动记录中保存搜索词或诗句内容。</p><div class="feedback" role="status">${esc(s.feedback)}</div></section>${nav()}</main>`}
function support(){return `<main class="shell personal-shell author-support-shell">${header()}<section class="personal-content author-support-content"><div class="personal-heading"><button class="icon-btn" data-action="me" aria-label="返回我的">${icon('chevron-left')}</button><h1>支持飞花令</h1></div><div class="author-support-intro"><p>如果您希望这个项目继续发展，可以请作者喝一杯奶茶。</p><p>您的支持是作者把项目继续下去的动力。</p></div><p class="author-support-adult">全部功能继续免费，赞赏不附带额外权益。请由家长或成年人自愿操作。</p><button class="${s.supportQrOpen?'secondary':'primary'} author-support-toggle" data-action="support-toggle" aria-expanded="${s.supportQrOpen}" aria-controls="author-support-code">${s.supportQrOpen?'收起微信赞赏码':'查看微信赞赏码'}</button><section id="author-support-code" class="author-support-code" ${s.supportQrOpen?'':'hidden'} aria-label="微信赞赏码">${s.supportQrOpen?`<figure class="author-support-figure"><img src="/assets/support-wechat-appreciation.png?v=1.5.0.1" width="494" height="494" alt="作者的微信赞赏码"></figure><p class="author-support-scan">微信扫描上方赞赏码，请作者喝杯奶茶 ☕</p><div class="author-support-links"><a href="/assets/support-wechat-appreciation-original.png?v=1.5.0.3" target="_blank" rel="noopener noreferrer">查看原图 ${icon('external-link')}</a><a href="/assets/support-wechat-appreciation.png?v=1.5.0.1" download="飞花令-微信赞赏码.png">保存赞赏码 ${icon('download')}</a></div><div class="author-support-help"><p>电脑浏览：用手机微信扫一扫，扫描上方赞赏码。</p><p>手机浏览：可尝试长按图片保存，或点“保存赞赏码”，再到微信扫一扫的相册中选择。</p><p>识别和赞赏请以微信内的实际页面为准。</p></div>`:''}</section><p class="author-support-thanks">谢谢你的使用与支持。</p>${active()?`<button class="secondary author-support-resume" data-action="support-resume">${icon('swords')}继续当前对局</button>`:''}</section>${nav()}</main>`}
const gameStatus=g=>g.status==='won'?'已完成':g.status==='abandoned'?'已结束':g.status==='lost'?'未完成':'进行中';
const displayTime=value=>value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(new Date(value*1000)):'未记录';
function records(){return `<main class="shell personal-shell">${header()}<section class="personal-content records-content"><div class="personal-heading"><button class="icon-btn" data-action="me" aria-label="返回我的">${icon('chevron-left')}</button><h1>对战记录</h1></div><section class="record-list" id="record-list">${s.records.map(g=>`<button class="record-row" data-record="${g.id}"><span class="record-token">${esc(g.word)}</span><span class="record-main"><strong>${esc(levels[g.difficulty]?.label||g.difficulty)} · ${gameStatus(g)}</strong><small>${displayTime(g.created_at)} · ${g.round} 轮</small></span>${icon('chevron-right')}</button>`).join('')}${!s.records.length&&!s.recordsLoading?'<div class="empty">还没有对战记录。<button class="secondary" data-action="home">去对战</button></div>':''}${s.recordsMore?`<button class="more-btn" data-action="more-records" ${s.recordsLoading?'disabled':''}>${s.recordsLoading?'加载中…':'查看更多'}</button>`:''}<div class="feedback">${esc(s.feedback)}</div></section></section>${nav()}</main>`}
function recordDetail(){const g=s.recordGame;const body=g?`<div class="record-summary"><strong>令字「${esc(g.word)}」</strong><span>${esc(levels[g.difficulty]?.label||g.difficulty)} · ${gameStatus(g)}</span><small>开始：${displayTime(g.created_at)}　结束：${displayTime(g.ended_at)}</small><small>完成 ${g.round} 轮 · 成功接令 ${g.player_answer_count??g.round} 次</small></div>${['playing','processing'].includes(g.status)?`<button class="primary" data-action="resume-record">继续对战</button>`:''}<section class="record-messages" id="record-messages">${g.messages[0]?.seq>1?`<button class="more-btn" data-action="older-record">查看更早记录</button>`:''}${history(g,'record')}</section>`:`<div class="empty">${s.feedback?'无法读取这局记录':'正在加载对战记录…'}</div>`;return `<main class="shell personal-shell">${header()}<section class="personal-content record-detail"><div class="personal-heading"><button class="icon-btn" data-action="records" aria-label="返回对战记录">${icon('chevron-left')}</button><h1>对战详情</h1></div>${body}<div class="feedback">${esc(s.feedback)}</div></section>${nav()}</main>`}
function render(){
    if(s.user?.must_change_password)s.page='me';
    const supportIdentity=s.page==='support'&&s.user?.id?`${identityEpoch}:${s.user.id}`:null;
    const enteringSupport=!!supportIdentity&&supportIdentity!==supportVisibleIdentity;
    if(enteringSupport)s.supportQrOpen=true;
    supportVisibleIdentity=supportIdentity;
    const accountForm=document.getElementById('account-form');
    const accountDraft=accountForm&&accountForm.dataset.identity===s.user?.id?{mode:accountForm.dataset.mode,values:Object.fromEntries(new FormData(accountForm))}:null;
    const h=document.getElementById('history'),top=h?.scrollTop||0;
    const anchor=h&&[...h.querySelectorAll('[data-seq]')].find(e=>e.getBoundingClientRect().bottom>h.getBoundingClientRect().top);
    const anchorSeq=anchor?.dataset.seq,anchorY=anchor?.getBoundingClientRect().top;
    const searchTop=document.getElementById('search-results')?.scrollTop||0;
    const recordTop=document.getElementById('record-list')?.scrollTop;
    if(recordTop!==undefined)recordScroll=recordTop;
    const detailTop=document.getElementById('record-messages')?.scrollTop||0;
    const supportTop=document.querySelector('.author-support-content')?.scrollTop||0;
    const focused=document.activeElement?.id,selection=document.activeElement?.selectionStart;
    applyAppearance();app.innerHTML=s.page==='battle'&&s.game?battle():s.page==='search'?search():s.page==='me'?me():s.page==='support'?support():s.page==='feedback'?feedbackPage():s.page==='records'?records():s.page==='record'?recordDetail():home();icons();
    if(enteringSupport)sendEvent('support_view');
    const nextAccountForm=document.getElementById('account-form');if(accountDraft&&nextAccountForm?.dataset.mode===accountDraft.mode&&nextAccountForm.dataset.identity===s.user?.id){for(const [name,value] of Object.entries(accountDraft.values)){const field=nextAccountForm.elements.namedItem(name);if(field)field.value=value}}
    const next=document.getElementById('history');if(next){next.scrollTop=top;const a=anchorSeq&&next.querySelector(`[data-seq="${anchorSeq}"]`);if(a&&anchorY!==undefined)next.scrollTop+=a.getBoundingClientRect().top-anchorY}
    const results=document.getElementById('search-results');if(results)results.scrollTop=searchTop;
    const recordList=document.getElementById('record-list');if(recordList)recordList.scrollTop=recordScroll;
    const detail=document.getElementById('record-messages');if(detail)detail.scrollTop=detailTop;
    const supportContent=document.querySelector('.author-support-content');if(supportContent)supportContent.scrollTop=supportTop;
    if(focused){const input=document.getElementById(focused);if(input&&!input.disabled&&input.tagName==='INPUT'){input.focus({preventScroll:true});if(selection!==null)try{input.setSelectionRange(selection,selection)}catch{}}}
    cancelAnimationFrame(renderFrame);renderFrame=requestAnimationFrame(()=>{if(wantBottom){const el=document.getElementById('history');if(el){el.scrollTop=el.scrollHeight;followBottom=true;unseen=false;document.querySelector('.latest-btn')?.setAttribute('hidden','')}wantBottom=false}});
}
async function latest(){const taskEpoch=identityEpoch;try{const r=await api('/api/games/'+s.game.id);s.game=r.game;receivedSeq=s.game.message_count;followBottom=true;unseen=false;wantBottom=true;render()}catch(e){if(taskEpoch!==identityEpoch)return;toast(e.message)}}
async function older(){const taskEpoch=identityEpoch;if(historyLoading)return;historyLoading=true;const gid=s.game.id,before=s.game.messages[0]?.seq;try{const r=await api(`/api/games/${gid}/messages?before=${before}`);if(gid!==s.game?.id)return;s.game.messages=[...r.items,...s.game.messages].slice(0,200);followBottom=false;render()}catch(e){if(taskEpoch!==identityEpoch)return;toast(e.message)}finally{if(taskEpoch!==identityEpoch)return;historyLoading=false;render()}}
async function loadRecords(append=false){const taskEpoch=identityEpoch;if(s.recordsLoading)return;s.recordsLoading=true;s.feedback='';render();try{const path='/api/games?limit=20'+(append&&s.recordsCursor?'&cursor='+encodeURIComponent(s.recordsCursor):'');const r=await api(path);s.records=append?[...s.records,...r.items]:r.items;s.recordsMore=r.has_more;s.recordsCursor=r.next_cursor;if(!append)recordScroll=0}catch(e){if(taskEpoch!==identityEpoch)return;s.feedback=e.message}finally{if(taskEpoch!==identityEpoch)return;s.recordsLoading=false;render()}}
async function openRecord(id){const taskEpoch=identityEpoch;if(s.recordLoading)return;s.recordLoading=true;s.recordGame=null;s.feedback='';s.page='record';location.hash='records/'+id;render();try{const r=await api('/api/games/'+id);if(location.hash!=='#records/'+id)return;s.recordGame=r.game;render()}catch(e){if(taskEpoch!==identityEpoch)return;if(location.hash==='#records/'+id){s.feedback=e.message;render()}}finally{if(taskEpoch!==identityEpoch)return;s.recordLoading=false}}
async function olderRecord(){const taskEpoch=identityEpoch;const g=s.recordGame;if(!g||!g.messages[0]||s.recordLoading)return;s.recordLoading=true;try{const r=await api(`/api/games/${g.id}/messages?before=${g.messages[0].seq}`);if(s.recordGame?.id===g.id){g.messages=[...r.items,...g.messages];render()}}catch(e){if(taskEpoch!==identityEpoch)return;toast(e.message)}finally{if(taskEpoch!==identityEpoch)return;s.recordLoading=false}}
async function saveStage(){const taskEpoch=identityEpoch;if(s.busy||s.stageDraft===s.stage)return;s.busy=true;render();let message='',kind='success';try{const r=await api('/api/me',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({education_stage:s.stageDraft})});s.stage=r.education_stage;message='设置已保存';s.feedback='';searchSeq++;s.searched=false;s.results=[];s.more=false;s.corpusVersion=''}catch(e){if(taskEpoch!==identityEpoch)return;message=e.message;kind='error';s.feedback=message}finally{if(taskEpoch!==identityEpoch)return;s.busy=false;render();if(message)toast(message,kind)}}
document.addEventListener('scroll',e=>{if(e.target.id!=='history'||wantBottom)return;const h=e.target;followBottom=h.scrollHeight-h.clientHeight-h.scrollTop<32;if(followBottom&&s.game.messages.at(-1)?.seq===s.game.message_count)unseen=false;const b=document.querySelector('.latest-btn');if(b)b.hidden=followBottom&&!unseen},true);
function openModal(title,body,kind='other'){lastFocus=document.activeElement;modalKind=kind;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-heading"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="关闭">${icon('x')}</button></div>${body}</section></div>`;icons();modalRoot.querySelector('button,input')?.focus()}
function closeModal(){if(reader.key==='full')stopReading();modalRoot.innerHTML='';modalKind='';if(lastFocus?.isConnected)lastFocus.focus();lastFocus=null}
function showThemes(){openModal('界面主题',`<div class="theme-options" role="radiogroup" aria-label="选择主题">${Object.entries(themes).map(([k,v])=>`<label class="theme-option"><img src="/assets/landscape-${k}.jpg" alt=""><span class="theme-info"><strong>${v.name}</strong></span><input type="radio" name="theme" value="${k}" aria-label="${v.name}" ${s.theme===k?'checked':''}></label>`).join('')}</div><button class="primary" data-action="close">完成 ${icon('check')}</button>`,'theme')}
function showCandidates(c){openModal('请选择对应诗句',`<p>请确认你想说的诗句，不限作答时间。</p>${c.map(o=>`<button class="candidate" data-candidate="${o.candidate_id}"><span class="result-line">${highlight(o.text)}</span><span class="result-source">${esc(o.author)}《${esc(o.title)}》</span></button>`).join('')}`,'candidates')}
function showResult(){
    const g=s.game;if(!g||active())return;
    const support=['won','lost'].includes(g.status)&&g.round>0?'<div class="result-support"><p>喜欢这样的诗词练习？<a href="/#support" target="_blank" rel="noopener noreferrer">支持作者</a></p><p class="result-support-note">赞赏完全自愿，不影响功能使用。请由家长或成年人自愿操作。</p></div>':'';
    openModal(g.status==='won'?'此局，你胜了':'下次，定有佳句',`<div class="result-icon">${icon(g.status==='won'?'trophy':'moon')}</div><p class="center">${esc(g.reason)}</p><div class="result-stats"><span><b>${g.round}</b>完成轮数</span><span><b>${g.round}</b>接令诗句</span><span><b>${g.level.label}</b>难度</span></div><button class="primary" data-action="again">再会一局</button><button class="secondary" data-action="review">回顾本局诗词</button><button class="secondary" data-action="search">去查诗</button>${support}`,'result')
}
async function lookup(append=false,track=true){const taskEpoch=identityEpoch;
    if(active()){toast('对局结束后可查诗');return}if(append&&s.searchLoading)return;
    const seq=++searchSeq,mode=s.mode,q=append?s.query:s.queryDraft,offset=append?s.results.length:0,stage=s.stage;
    s.searchLoading=true;s.feedback='';render();
    try{const path=mode==='word'?'/api/search?unit=pair&word='+encodeURIComponent(q):'/api/works?mode='+mode+'&q='+encodeURIComponent(q);
        const r=await api(path+'&offset='+offset+'&stage='+stage,track&&!append?{headers:{'X-Activity-ID':requestId()}}:{});if(seq!==searchSeq||s.mode!==mode||s.stage!==stage)return;
        if(append&&s.corpusVersion&&s.corpusVersion!==r.corpus_version){s.results=[];s.more=false;s.corpusVersion='';s.searchLoading=false;lookup();return}
        stopReading();s.query=r.word||r.query;s.queryDraft=s.query;s.results=append?[...s.results,...r.items]:r.items;s.total=r.total;s.more=r.has_more;s.searched=true;
        s.corpusVersion=r.corpus_version;
        if(!append){const el=document.getElementById('search-results');if(el)el.scrollTop=0}
    }catch(e){if(taskEpoch!==identityEpoch)return;if(seq===searchSeq)s.feedback=e.message}finally{if(taskEpoch!==identityEpoch)return;if(seq===searchSeq){s.searchLoading=false;render()}}
}
async function start(){const taskEpoch=identityEpoch;if(s.busy)return;s.busy=true;s.feedback='';render();try{const r=await api('/api/games',json({word:s.word,difficulty:s.difficulty,request_id:requestId()}));s.answer='';resultShown='';s.game=r.game;receivedSeq=0;followBottom=true;wantBottom=true;store.set('feihualing.game',r.game.id);go('battle')}catch(e){if(taskEpoch!==identityEpoch)return;s.feedback=e.message}finally{if(taskEpoch!==identityEpoch)return;s.busy=false;render()}}
function supportNavigation(page){return ['me','support','feedback','records','record'].includes(s.page)&&['me','support','feedback','records'].includes(page)}
function go(page){if(s.user?.must_change_password&&page!=='me'){toast('请先修改临时密码');return}if(page!=='battle'&&active()&&!(s.page==='record'&&['records','me'].includes(page))&&!supportNavigation(page)){toast('请先结束当前对局');return}const previous=s.page;stopReading();closeModal();s.feedback='';s.page=page;location.hash=page;render();window.scrollTo(0,0);if(page==='search'&&!s.searched&&s.mode==='word')lookup(false,false);if(page==='records'&&(previous!=='record'||!s.records.length))loadRecords()}
async function execute(operation){const taskEpoch=identityEpoch;if(s.busy)return;s.busy=true;pending=operation;s.feedback='';render();try{const r=await api(operation.path,operation.options);pending=null;s.busy=false;if(r.verdict?.kind==='accepted'){s.answer='';followBottom=true;wantBottom=true}setGame(r.game);s.feedback=r.verdict?.message||'';render();if(r.verdict?.kind==='candidates')showCandidates(r.verdict.candidates);if(r.verdict?.kind==='hint')openModal('借一缕诗意',`<p class="center">${esc(r.verdict.dynasty)} · ${esc(r.verdict.author)}</p><div class="modal-poem">《${esc(r.verdict.title)}》</div><button class="primary" data-action="close">继续接令</button>`);if(r.verdict?.corrected)toast(r.verdict.message)}catch(e){if(taskEpoch!==identityEpoch)return;s.feedback=e.message;if(!s.network)pending=null}finally{if(taskEpoch!==identityEpoch)return;s.busy=false;render()}}
function submit(){if(!s.answer.trim()||!active()||s.game.status==='processing'||s.busy)return;execute({path:`/api/games/${s.game.id}/answers`,options:json({text:s.answer,request_id:requestId()})})}
function action(name,value=''){closeModal();return execute({path:`/api/games/${s.game.id}/${name}`,options:json({request_id:requestId(),candidate_id:value})})}
async function fullPoem(pid){const taskEpoch=identityEpoch;try{const p=await api('/api/poems/'+pid,{headers:{'X-Activity-ID':requestId()}});stopReading();fullPoemText=`${p.title}，${p.author}。${p.paragraphs.join('\n')}`;const source=p.source_url?`<a href="${esc(p.source_url)}" target="_blank" rel="noopener noreferrer">${esc(p.source_label)}</a>${p.verification==='unreviewed'?' · 待教材复核':''}`:esc(p.source);openModal(p.title,`<div class="modal-source">${esc(p.dynasty)} · ${esc(p.author)}</div><div class="modal-poem">${p.paragraphs.map(t=>`<p>${highlight(t,s.query)}</p>`).join('')}</div><p>来源：${source}</p><div class="modal-commands">${readerButton('full','朗读全文')}<button class="secondary" data-copy="${esc(p.paragraphs.join('\n'))}">复制全文</button></div>`)}catch(e){if(taskEpoch!==identityEpoch)return;toast(e.message)}}
async function copy(t){const taskEpoch=identityEpoch;try{await navigator.clipboard.writeText(t);toast('已复制')}catch{openModal('长按复制诗句',`<p style="user-select:all">${esc(t)}</p>`)}}
async function poll(){const taskEpoch=identityEpoch;if(polling||s.busy)return;polling=true;try{if(s.page==='battle'&&active()){const r=await api('/api/games/'+s.game.id+'?after='+receivedSeq);setGame(r.game)}}catch{}finally{if(taskEpoch!==identityEpoch)return;polling=false}}
document.addEventListener('input',e=>{if(e.target.id==='word')s.word=e.target.value;if(e.target.id==='answer')s.answer=e.target.value;if(e.target.id==='search-word')s.queryDraft=e.target.value});
document.addEventListener('change',e=>{if(e.target.name==='theme'){s.theme=e.target.value;store.set('feihualing.theme',s.theme);render();lastFocus=document.querySelector('[data-action="theme"]')}if(e.target.name==='stage'){s.stageDraft=e.target.value;const save=document.querySelector('[data-action="save-stage"]');if(save)save.disabled=s.stageDraft===s.stage}});
document.addEventListener('compositionstart',e=>{if(e.target.id==='answer')composing=true});
document.addEventListener('compositionend',e=>{if(e.target.id==='answer'){composing=false;s.answer=e.target.value}});
document.addEventListener('submit',e=>{if(['account-form','feedback-form'].includes(e.target.id))return;e.preventDefault();if(e.target.id==='answer-form'&&!composing)submit();if(e.target.id==='search-form')lookup()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
    if(b.dataset.read?.startsWith('record-')){e.stopPropagation();const seq=Number(b.dataset.read.slice(7)),message=s.recordGame?.messages.find(m=>m.seq===seq);if(message)readText(b.dataset.read,message.text);return}
    if(b.dataset.record){e.stopPropagation();openRecord(b.dataset.record);return}
    const a=b.dataset.action;
    if(a==='save-stage'){e.stopPropagation();saveStage()}
    if(a==='records'){e.stopPropagation();go('records')}
    if(a==='me'){e.stopPropagation();go('me')}
    if(a==='feedback'){e.stopPropagation();go('feedback')}
    if(a==='support'){e.stopPropagation();go('support')}
    if(a==='support-toggle'){e.stopPropagation();s.supportQrOpen=!s.supportQrOpen;if(s.supportQrOpen)sendEvent('support_view');render();document.querySelector('[data-action="support-toggle"]')?.focus({preventScroll:true})}
    if(a==='support-resume'){e.stopPropagation();go('battle')}
    if(a==='home'){e.stopPropagation();go('home')}
    if(a==='more-records'){e.stopPropagation();loadRecords(true)}
    if(a==='older-record'){e.stopPropagation();olderRecord()}
    if(a==='resume-record'&&s.recordGame){e.stopPropagation();s.game=s.recordGame;receivedSeq=s.game.message_count;wantBottom=true;followBottom=true;store.set('feihualing.game',s.game.id);s.recordGame=null;go('battle')}
},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.read){const key=b.dataset.read,text=key==='full'?fullPoemText:key.startsWith('battle-')?s.game?.messages.find(m=>m.seq===Number(key.slice(7)))?.text:s.results[Number(key.slice(7))]?.text;if(text)readText(key,text);return}if(b.dataset.mode){stopReading();searchSeq++;s.mode=b.dataset.mode;s.queryDraft='';s.query='';s.results=[];s.total=0;s.more=false;s.searched=false;s.searchLoading=false;s.feedback='';render();return}if(b.dataset.word){s.word=b.dataset.word;render()}if(b.dataset.level){s.difficulty=b.dataset.level;render()}if(b.dataset.query){s.queryDraft=b.dataset.query;lookup()}if(b.dataset.poem)fullPoem(b.dataset.poem);if(b.dataset.copy)copy(b.dataset.copy);if(b.dataset.candidate)action('confirm',b.dataset.candidate);const a=b.dataset.action;if(a==='theme')showThemes();if(a==='close')closeModal();if(a==='start')start();if(a==='search')go('search');if(a==='more')lookup(true);if(a==='older')older();if(a==='latest')latest();if(a==='search-start'){s.word=s.query;go('home')}if(a==='hint')action('hint');if(a==='retry'&&pending)execute(pending);if(a==='exit')openModal('离开这场诗会？','<p>离开后本局结束。</p><button class="primary" data-action="end">离开对局</button><button class="secondary" data-action="close">继续接令</button>');if(a==='end'){await action('end');go('home')}if(a==='again'){s.word=s.game.word;s.difficulty=s.game.difficulty;go('home');start()}if(a==='result')showResult();if(a==='review'){closeModal();latest()}if(a==='rules')openModal('飞花令怎么玩','<p>选一个汉字，与诗友轮流接诗。每句必须含令字，双方不能重复。可输入一句或同一作品的相邻上下句，上下句均计入已用诗句。</p><p>全部模式不限时。简单 5 轮，可提示 2 次；正常 10 轮、困难 15 轮，无提示；无限模式不限回合、不限提示，直到无诗可接或主动结束。答错可重试。</p><p>电脑优先接自然成对的上下句，你可答一句或相邻两句。输入后点击发送核对诗句。可随时思考、查看提示或切换主题。</p>');if(a==='about')openModal('诗词与素材来源','<p>唐宋诗词：chinese-poetry 开源数据库（MIT）与本项目常见诗词校对集。古籍异文与原始录入错误可能存在。</p><p>山水画：王翚《仿古山水册》，大都会艺术博物馆公开领域馆藏。</p><p>诗词朗读使用浏览器或设备自带语音能力，不在网站服务器保存音频。</p>')});
document.addEventListener('keydown',e=>{if(e.target.id==='answer'&&e.key==='Enter'&&(e.isComposing||composing||e.keyCode===229)){e.preventDefault();return}if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modalKind){const nodes=[...modalRoot.querySelectorAll('button:not(:disabled),input,a')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(s.user?.must_change_password&&p!=='me'){window.history.replaceState(null,'','#me');s.page='me';render();toast('请先修改临时密码');return}if(p===s.page)return;if(p.startsWith('records/')){const id=p.slice(8);if(!/^[a-f0-9]{32}$/.test(id))return;if(s.recordGame?.id!==id&&!s.recordLoading)openRecord(id);return}if(active()&&p!=='battle'&&!(s.page==='record'&&['records','me'].includes(p))&&!supportNavigation(p)){location.hash='battle';toast('请先结束当前对局');return}if(['home','search','battle','me','records','support','feedback'].includes(p)){stopReading();s.page=p==='battle'&&!s.game?'home':p;closeModal();render();if(p==='search'&&!s.searched&&s.mode==='word')lookup(false,false);if(p==='records'&&!s.records.length)loadRecords()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopReading();else poll()});
window.addEventListener('online',poll);window.addEventListener('pagehide',stopReading);
function fitViewport(){
    const viewport=window.visualViewport,stay=followBottom,field=document.activeElement;
    document.documentElement.style.setProperty('--view-height',(viewport?.height||window.innerHeight)+'px');
    const keyboardOpen=window.innerWidth<600&&(viewport?.height||window.innerHeight)<600&&field?.matches('input:not([type=radio]):not([type=checkbox]),textarea');
    document.body.classList.toggle('keyboard-open',!!keyboardOpen);
    if(keyboardOpen&&field.closest('.personal-shell'))requestAnimationFrame(()=>{
        if(field!==document.activeElement||!field.isConnected)return;
        const rect=field.getBoundingClientRect(),top=(viewport?.offsetTop||0)+12,bottom=(viewport?.offsetTop||0)+(viewport?.height||window.innerHeight)-18;
        if(rect.bottom>bottom)window.scrollBy(0,rect.bottom-bottom);
        else if(rect.top<top)window.scrollBy(0,rect.top-top);
    });
    if(stay&&s.page==='battle')requestAnimationFrame(()=>{const h=document.getElementById('history');if(h)h.scrollTop=h.scrollHeight});
}
window.visualViewport?.addEventListener('resize',fitViewport);window.addEventListener('resize',fitViewport);document.addEventListener('focusin',fitViewport);document.addEventListener('focusout',fitViewport);fitViewport();
setInterval(poll,4000);
boot();
})();
